function renderBuffDrawer(member) {
  // 2026-08-22 站长要求：右侧「Buff来源」Tab/抽屉已移除（无元素即不触发事件）
  return '';
}


function getCheckZoneDef(zoneId) {
  if (zoneId === 'all') return { id: 'all', label: '全部', cats: [] };
  return (
    BUFF_DAMAGE_ZONE_GROUPS.find((z) => z.id === zoneId) ||
    BUFF_DAMAGE_ZONE_GROUPS.find((z) => z.id === 'bonus') ||
    BUFF_DAMAGE_ZONE_GROUPS[0]
  );
}

function buffBelongsToCheckZone(buff, zone) {
  if (!buff || !zone) return false;
  if (isConvergenceBuffCategory(buff.category) && zone.id !== 'vuln' && zone.id !== 'all') return false;
  if (zone.id === 'all') return true;
  if (zone.cats.includes(buff.category)) return true;
  // 复合 Buff：按各效果乘区归入对应检查列
  if (buff.category === 'composite') {
    return (buff.effects || []).some((fx) => fx?.zone && zone.cats.includes(fx.zone));
  }
  return false;
}

function formatCheckZoneValue(zoneId, bd) {
  if (!bd || bd.fixedDamage) return '—';
  const asPct = (factor) => `${((Number(factor) || 0) * 100).toFixed(1)}%`;
  switch (zoneId) {
    case 'mult':
      return asPct(getDisplayedSkillMult(bd));
    case 'atk':
      return Math.round(Number(bd.attack) || 0).toLocaleString('zh-CN');
    case 'deep':
      return asPct(bd.deepening);
    case 'bonus':
      return asPct(bd.dmgBonus);
    case 'critRate':
      return `${(Number(bd.critRatePct) || 0).toFixed(1)}%`;
    case 'critDmg':
      return `${(Number(bd.critDmgPct) || 0).toFixed(1)}%`;
    case 'crit':
      return asPct(bd.critExpect);
    case 'res':
      return asPct(bd.resistance);
    case 'def':
      return asPct(bd.defense);
    case 'vuln': {
      const v1 = Number(bd.vulnerability) || 0;
      const conv = Number.isFinite(Number(bd.convergenceVuln)) ? Number(bd.convergenceVuln) : 1;
      const v2 = Number.isFinite(Number(bd.extraVulnerability))
        ? Number(bd.extraVulnerability)
        : 1;
      return asPct(v1 * conv * (bd.matrixFinal ?? 1) * (bd.bossFinal ?? 1) * v2);
    }
    case 'harmony':
      return Number.isFinite(Number(bd.harmonyBreakAmpPct))
        ? `${Number(bd.harmonyBreakAmpPct).toFixed(1)}%`
        : '—';
    default:
      return '—';
  }
}

function formatCheckFinalMult(bd, catalogItem) {
  if (bd?.fixedDamage) return String(Math.round(Number(bd.baseMult) || 0));
  if (bd && Number.isFinite(bd.skillMult)) return `${(getDisplayedSkillMult(bd) * 100).toFixed(1)}%`;
  if (catalogItem && isFixedDamageUnit(catalogItem)) return String(Math.round(Number(catalogItem.baseMult) || 0));
  if (catalogItem && Number.isFinite(catalogItem.baseMult)) return `${(Number(catalogItem.baseMult) * normalizeMultCount(catalogItem.multCount)).toFixed(1)}%`;
  return '—';
}

function formatCheckSkillDamage(bd) {
  if (!bd || !Number.isFinite(Number(bd.total))) return '—';
  return fmt(Number(bd.total) || 0);
}

function formatCheckBuffTooltip(buff, member) {
  if (!buff) return '';
  const cat = BUFF_CATS[buff.category]?.label || buff.category || '';
  const src = buff.teamSourceId ? '全队 Buff' : buff.personalSourceId ? '个人 Buff（已同步）' : '个人 Buff';
  const stacks = member?.globalBuffStacks?.[buff.id];
  let valueLine = '';
  if (buff.category === 'composite') {
    const effects = (buff.effects || [])
      .map((fx) => {
        const z = BUFF_CATS[fx.zone]?.label || fx.zone || '';
        const v = Number(fx.value ?? fx.perStack) || 0;
        return `${z} ${formatBuffPct(v)}`;
      })
      .filter(Boolean);
    valueLine = effects.length ? `复合，${effects.join('（')}` : '复合效果';
  } else if (isStackBuff(buff)) {
    const eff = getBuffEffectiveValue(buff, { [buff.id]: stacks ?? 0 });
    valueLine = `每层 ${formatBuffPct(buff.perStack ?? buff.value)} · 当前层${stacks ?? 0} →${formatBuffPct(eff)}`;
  } else {
    valueLine = `数值${formatBuffPct(buff.value)}`;
  }
  const typeExtra =
    buff.damageType === '效应'
      ? ` · 类型 效应·${normalizeBuffEffectType(buff.effectType)}`
      : buff.damageType
        ? ` · 类型 ${buff.damageType}`
        : '';
  const elExtra = buff.element && buff.element !== BUFF_ELEMENT_GENERAL ? ` · 属性${buff.element}` : '';
  return `${formatBuffDisplayName(buff)}\n来源，${src}\n乘区，${cat}${typeExtra}${elExtra}\n${valueLine}`;
}

/** 与伤害计算一致：类型/属性Buff 仅在与技能匹配时视为生效 */
function buffAppliesToUnit(buff, unit, parentSkill, member, zone) {
  if (!buff || !unit) return false;
  const damageType = getUnitDamageType(unit, parentSkill);
  if (damageType === '效应' && window.__WC.isQianxiaoXuwuwenhenBuff(buff)) return false;
  const damageElement = getUnitDamageElement(unit, parentSkill, member);
  const alsoDamageTypes = getUnitAlsoDamageTypes(unit, parentSkill, member);
  const combatMode = resolvePhoebeCombatMode(unit, parentSkill, member);
  const typedOpts = {
    unit,
    parentSkill,
    damageElement,
    effectType: getUnitEffectType(unit, parentSkill, member),
    alsoDamageTypes,
    member,
    combatMode,
  };
  if (typeof buffMatchesResolvedCombatMode === 'function' && !buffMatchesResolvedCombatMode(buff, typedOpts)) {
    return false;
  }

  if (isCompositeBuff(buff)) {
    const zoneCats = !zone || zone.id === 'all' ? null : zone.cats || null;
    return (buff.effects || []).some((rawFx) => {
      if (!compositeEffectMeetsMinResonance(rawFx, member, buff)) return false;
      if (!compositeEffectMeetsTargetFilters(rawFx, member)) return false;
      const effect = resolveCompositeEffectRuntime(buff, rawFx);
      const cat = effect?.zone;
      if (!cat) return false;
      if (zoneCats && !zoneCats.includes(cat)) return false;
      if (!compositeEffectMatchesFilters(effect, cat, damageType, typedOpts)) {
        return false;
      }
      return compositeEffectAppliesToUnit(effect, unit, parentSkill, member);
    });
  }

  const cat = buff.category;
  if (cat === 'matrixFinal') {
    const zoneClass = buff.matrixSource?.zoneClass ?? 6;
    if (zone?.id && zone.id !== 'all' && zoneClass !== ({vuln:2,matrix:6,boss:8}[zone.id] ?? 6)) return false;
    if (zone?.cats?.length && zone.id !== 'all' && !zone.cats.includes(cat) && !(zone.id === 'vuln' && zoneClass === 2)) return false;
    return window.__WC.matchesMatrixFinalBuff(buff, damageType, typedOpts);
  }
  if (zone?.cats?.length && !zone.cats.includes(cat) && cat !== 'composite' && zone.id !== 'all') {
    return false;
  }
  if (TYPED_BUFF_CATS.has(cat)) {
    return typedBuffMatchesDamageContext(
      buff,
      damageType,
      typedOpts.effectType,
      typedOpts
    );
  }
  if (ELEMENT_TYPED_BUFF_CATS.has(cat)) {
    return !!damageElement && (buff.element || '') === damageElement;
  }
  return true;
}

function isCheckBuffCoveringColumn(buff, col, member, zone) {
  if (!buff || !col?.linked || !col.link?.skill || !col.link?.phase) return false;
  const { skill, phase } = col.link;
  if (buffNeedsUnitMatch(buff) && !skillBuffCanApply(skill, buff, member)) return false;
  const phaseActive = getPhaseActive(phase, member);
  return collectSkillBuffUnits(skill).some((unit) => {
    // 与伤害结算一致：锁定技能读 frozenBuffActive，避免 ✓/× 与表头伤害脱节
    const active = getUnitActive(unit, phaseActive, skill.split ? skill : null);
    if (!active[buff.id]) return false;
    const parent = skill.split ? skill : null;
    return buffAppliesToUnit(buff, unit, parent, member, zone);
  });
}

/** 检查格状态：可点切换单技能勾选/ 不匹配/ 未入轴*/
function getCheckBuffCellState(buff, col, member, zone) {
  if (!buff || !col?.linked || !col.link?.skill || !col.link?.phase) {
    return { kind: 'na' };
  }
  const { skill, phase } = col.link;
  if (buffNeedsUnitMatch(buff) && !skillBuffCanApply(skill, buff, member)) {
    return {
      kind: 'mismatch',
      why: describeBuffUnitMismatch(
        buff,
        collectSkillBuffUnits(skill)[0] || skill,
        skill.split ? skill : null,
        member
      ),
    };
  }
  const covered = isCheckBuffCoveringColumn(buff, col, member, zone);
  return {
    kind: skill.locked ? 'locked' : 'toggle',
    covered,
    phaseId: phase.id,
    skillId: skill.id,
    buffId: buff.id,
  };
}

/** 检查页技能伤害上下文：多轮时与计算页一致，走当前编辑轮 */
function getCheckSkillBreakdownContext(phase, skill, member) {
  if (member?.cycleConfig?.enabled && typeof getSkillBreakdownContextForRound === 'function') {
    const roundIndex =
      typeof getActiveCycleRoundIndex === 'function' ? getActiveCycleRoundIndex(member) : 0;
    return getSkillBreakdownContextForRound(phase, skill, member, roundIndex);
  }
  return getSkillBreakdownContext(phase, skill, member);
}

function getCheckAxisColumns(member) {
  // 与乘区对照表一致：按编轴视觉左→右（axisOffsetPx）排序，避免复制后数组序与轴序脱节
  if (typeof computeSpecialSkills === 'function') computeSpecialSkills();
  const catalog = [...(member.rotationCatalog || [])];
  catalog.sort((a, b) => {
    const oa =
      typeof getCatalogAxisOffset === 'function'
        ? getCatalogAxisOffset(a) ?? (Number(a.axisOffsetPx) || 0)
        : Number(a.axisOffsetPx) || 0;
    const ob =
      typeof getCatalogAxisOffset === 'function'
        ? getCatalogAxisOffset(b) ?? (Number(b.axisOffsetPx) || 0)
        : Number(b.axisOffsetPx) || 0;
    if (oa !== ob) return oa - ob;
    return 0;
  });
  return catalog.map((item) => {
    const isSpecial =
      typeof isAxisLinkedSpecialCatalogEntry === 'function' &&
      isAxisLinkedSpecialCatalogEntry(item);
    if (isSpecial) {
      const special = findSpecialSkill(item.linkedSpecialSkillId);
      let breakdown = special?._breakdown || null;
      if (!breakdown && special) {
        breakdown =
          special.kind === 'effect'
            ? calcEffectBreakdown(special)
            : calcExecutionBreakdown(special);
      }
      return {
        catalogId: item.id,
        name: item.name || special?.name || '特殊技能',
        linked: !!special,
        link: null,
        isSpecial: true,
        breakdown,
        catalogItem: item,
      };
    }
    const link = getCatalogTimelineLink(item.id, member);
    let breakdown = null;
    if (link?.skill && link?.phase) {
      const ctx = getCheckSkillBreakdownContext(link.phase, link.skill, member);
      breakdown = ctx.breakdown;
    }
    return {
      catalogId: item.id,
      name: item.name || '未命名',
      linked: !!link,
      link: link || null,
      isSpecial: false,
      breakdown,
      catalogItem: item,
    };
  });
}

function getCheckZoneBuffLists(member, zoneId) {
  const zone = getCheckZoneDef(zoneId);
  const list = (member.buffs || []).filter((b) => buffBelongsToCheckZone(b, zone));
  const team = list.filter((b) => b.teamSourceId);
  const personal = list.filter((b) => !b.teamSourceId);
  return { zone, team, personal };
}

/** Excel 对照用：去掉多余尾零，保留足够精应*/
function formatCheckExcelNumber(value, maxDigits = 9) {
  if (!Number.isFinite(Number(value))) return '';
  const n = Number(value);
  if (Number.isInteger(n) || Math.abs(n - Math.round(n)) < 1e-12) return String(Math.round(n));
  let s = n.toFixed(maxDigits);
  // 只在有小数位时去尾零；整数串（如 toFixed(0) 的 "11600"）不得删整数尾零
  if (s.indexOf('.') >= 0) s = s.replace(/\.?0+$/, '');
  return s;
}

function formatCheckExcelMultPct(skillMult) {
  if (!Number.isFinite(Number(skillMult))) return '';
  return `${(Number(skillMult) * 100).toFixed(2)}%`;
}

function formatCheckExcelCritRate(bd) {
  if (!bd || !Number.isFinite(Number(bd.critRatePct))) return '';
  return formatCheckExcelNumber(Number(bd.critRatePct) / 100, 6);
}

function formatCheckExcelCritDmg(bd) {
  if (!bd || !Number.isFinite(Number(bd.critDmgPct))) return '';
  return formatCheckExcelNumber(Number(bd.critDmgPct) / 100, 6);
}

/** 乘区对照表「类型」列微型标签 class */
function getCheckExcelTypeTagClass(type) {
  switch (String(type || '').trim()) {
    case '普攻':
      return 'type-normal';
    case '共鸣技能':
      return 'type-skill';
    case '重击':
      return 'type-heavy';
    case '共鸣解放':
      return 'type-liberation';
    case '变奏':
      return 'type-intro';
    case '延奏':
      return 'type-outro';
    case '声骸':
      return 'type-echo';
    case '效应':
      return 'type-effect';
    case '处决':
      return 'type-exec';
    default:
      return '';
  }
}

/**
 * 按编轴左→右顺序生成 Excel 乘区对照行（含轴上特殊技能处决） */
function getCheckExcelAxisRows(member) {
  if (!member) return [];
  if (typeof computeSpecialSkills === 'function') computeSpecialSkills();
  const catalog = [...(member.rotationCatalog || [])];
  catalog.sort((a, b) => {
    const oa =
      typeof getCatalogAxisOffset === 'function'
        ? getCatalogAxisOffset(a) ?? (Number(a.axisOffsetPx) || 0)
        : Number(a.axisOffsetPx) || 0;
    const ob =
      typeof getCatalogAxisOffset === 'function'
        ? getCatalogAxisOffset(b) ?? (Number(b.axisOffsetPx) || 0)
        : Number(b.axisOffsetPx) || 0;
    if (oa !== ob) return oa - ob;
    return 0;
  });

  const rows = [];
  catalog.forEach((item) => {
    const isSpecialLink =
      typeof isAxisLinkedSpecialCatalogEntry === 'function' &&
      isAxisLinkedSpecialCatalogEntry(item);

    if (isSpecialLink) {
      const special = findSpecialSkill(item.linkedSpecialSkillId);
      let bd = special?._breakdown || null;
      if (!bd && special) {
        bd =
          special.kind === 'effect'
            ? calcEffectBreakdown(special)
            : calcExecutionBreakdown(special);
      }
      const kind = special?.kind === 'effect' ? 'effect' : 'execution';
      const type = kind === 'effect' ? '效应' : '处决';
      rows.push({
        type,
        name: item.name || special?.name || type,
        isSpecial: true,
        kind,
        linked: !!special,
        bd,
        rowKey: `special:${item.linkedSpecialSkillId || item.id}`,
        typeTagClass: getCheckExcelTypeTagClass(type),
      });
      return;
    }

    const link = getCatalogTimelineLink(item.id, member);
    let bd = null;
    let type = item.damageType || '';
    if (link?.skill && link?.phase) {
      const ctx = getCheckSkillBreakdownContext(link.phase, link.skill, member);
      type = getUnitDamageType(link.skill, null) || type;
      // 仅当用户在编轴/时间线里主动把技能拆成 hit（skill.split）时才按 hit 拆行；
      // multComponents 自动分段（未拆）的技能保持整行聚合展示。
      const trulySplit =
        !!link.skill.split &&
        Array.isArray(link.skill.hits) &&
        link.skill.hits.length > 1 &&
        Array.isArray(ctx.hitBreakdowns) &&
        ctx.hitBreakdowns.length > 1;
      if (trulySplit) {
        ctx.hitBreakdowns.forEach((hitBd, hi) => {
          rows.push({
            type,
            name: `${item.name || link.skill.name || '技能'}，${hi + 1}hit`,
            isSpecial: false,
            linked: true,
            bd: hitBd,
            rowKey: `${item.id}:${hi}`,
            catalogId: item.id,
            skillId: link.skill.id,
            phaseId: link.phase.id,
            hitIndex: hi,
            hitContext: ctx.hits && ctx.hits[hi],
            typeTagClass: getCheckExcelTypeTagClass(type),
          });
        });
        return;
      }
      bd = ctx.breakdown;
    }
    const typeLabel = type || '—';
    rows.push({
      type: typeLabel,
      name: item.name || '未命名',
      isSpecial: false,
      linked: !!link,
      bd,
      rowKey: item.id,
      catalogId: item.id,
      skillId: link?.skill?.id || '',
      phaseId: link?.phase?.id || '',
      hitIndex: null,
      hitContext: null,
      typeTagClass: getCheckExcelTypeTagClass(typeLabel),
    });
  });
  return rows;
}

function renderCheckExcelRowCells(row, showConv = false, showMatrix = false, showBoss = false) {
  const bd = row.bd;
  if (!bd) {
    return Array(13 + Number(showConv) + Number(showMatrix) + Number(showBoss))
      .fill('<td class="check-excel-na">—</td>')
      .join('');
  }
  const rowKey = String(row.rowKey || row.catalogId || '');
  const zoneCell = (zoneId, html, title, isKey = false, extraCls = '') =>
    `<td class="check-excel-num${isKey ? ' is-key' : ''}${extraCls ? ` ${extraCls}` : ''}" data-check-zone-cell="${zoneId}" data-check-row-key="${escapeHtml(rowKey)}" title="${escapeHtml(title || '点击查看该乘区数值构成')}">${html}</td>`;
  if (bd.fixedDamage) {
    const fixed = formatCheckExcelNumber(bd.total, 6);
    const na = () => '<td class="check-excel-na">—</td>';
    return [
      `<td title="固定伤害">${formatCheckExcelNumber(bd.baseMult, 2)}</td>`,
      na(), na(), na(), na(), na(), na(), na(), na(),
      `<td class="check-excel-total">${fixed}</td>`,
      `<td class="check-excel-crit" title="固定伤害无暴击区分">${fixed}</td>`,
      na(),
      `${showConv ? na() : ''}`,
      showMatrix ? na() : '',
      showBoss ? na() : '',
      na(),
    ].join('');
  }

  const isSpecial = !!row.isSpecial;
  const mult = formatCheckExcelMultPct(getDisplayedSkillMult(bd));
  // 特殊技能：基数（0027/3674）已内置不展示；加深列填效应加深；攻击留空  // 增伤列：处决=谐幅，效应加深（与现逻辑一致）
  const deepen = isSpecial
    ? formatCheckExcelNumber(bd.effectDeepening ?? bd.deepening, 6)
    : formatCheckExcelNumber(bd.deepening, 6);
  const attack = isSpecial ? '' : formatCheckExcelNumber(bd.attack, 6);
  const bonus = isSpecial
    ? formatCheckExcelNumber(
        row.kind === 'execution' ? bd.harmonyBreakAmp ?? bd.dmgBonus : bd.dmgBonus,
        6
      )
    : formatCheckExcelNumber(bd.dmgBonus, 6);
  const critRate = formatCheckExcelCritRate(bd);
  const critDmg = formatCheckExcelCritDmg(bd);
  const critExpect = formatCheckExcelNumber(bd.critExpect, 4);
  const res = formatCheckExcelNumber(bd.resistance, 6);
  const def = formatCheckExcelNumber(bd.defense, 4);
  const vuln = formatCheckExcelNumber(bd.vulnerability, 6);
  const convVuln = formatCheckExcelNumber(bd.convergenceVuln ?? 1, 6);
  const extraVuln = formatCheckExcelNumber(bd.extraVulnerability ?? 1, 6);
  const total = formatCheckExcelNumber(bd.total, 0);
  const critTotal = formatCheckExcelNumber(
    Number.isFinite(bd.critTotal) ? bd.critTotal : bd.total,
    0
  );

  return [
    zoneCell('mult', mult || '—', '倍率：基础 + 倍率增加 + 倍率提升（区内加算）', true),
    zoneCell('deep', deepen || '—', '加深：泛用/属性/类型加深加算'),
    zoneCell('atk', attack || '—', '攻击：面板来源 + 攻击类 Buff', true),
    zoneCell('bonus', bonus || '—', '增伤：面板来源 + 泛用/属性/类型增伤加算'),
    zoneCell('critRate', critRate || '—', '暴击：面板来源 + 暴击类 Buff'),
    zoneCell('critDmg', critDmg || '—', '暴伤：面板来源 + 暴伤类 Buff'),
    zoneCell('critExpect', critExpect || '—', '暴击期望 = 暴击率×暴伤 + (1−暴击率)', true),
    zoneCell('res', res || '—', '抗性：基础抗性 − 减抗（超 100% 减半）'),
    zoneCell('def', def || '—', '防御：1520 / (等级项×(1−穿防)×(1−无视)+1520)'),
    zoneCell('total', total || '—', '最终期望：各乘区连乘后按暴击率加权（取整显示）', false, 'check-excel-total'),
    zoneCell('critTotal', critTotal || '—', '全暴击时各段 Floor 后合计', false, 'check-excel-crit'),
    zoneCell('vuln', vuln || '—', '易伤：泛用/属性/类型易伤加算'),
    `${showConv ? zoneCell('conv', convVuln || '—', '集谐·最终伤害') : ''}`,
    showMatrix ? zoneCell('matrix', formatCheckExcelNumber(bd.matrixFinal ?? 1, 6), '第6类易伤·矩阵：同区相加，与6链独立乘算') : '',
    showBoss ? zoneCell('boss', formatCheckExcelNumber(bd.bossFinal ?? 1, 6), '第8类易伤·Boss：独立乘算') : '',
    zoneCell('extraVuln', extraVuln || '—', '额外易伤'),
  ].join('');
}

function renderCheckExcelTable(member) {
  const rows = getCheckExcelAxisRows(member);
  const showConv = rows.some((r) => Number(r.bd?.convergenceVulnPct) > 0);
  const showMatrix = rows.some(r => Number(r.bd?.matrixFinalPct) > 0);
  const showBoss = rows.some(r => Number(r.bd?.bossFinalPct || 0) !== 0);
  const body = rows.length
    ? rows
        .map((row, i) => {
          const miss = !row.linked ? ' is-unlinked' : '';
          const typeCls = row.typeTagClass ? ` ${row.typeTagClass}` : '';
          const rowTypeCls = row.typeTagClass ? ` row-${row.typeTagClass}` : '';
          return `<tr class="check-excel-row${miss}${rowTypeCls}">
            <td class="check-excel-type"><span class="check-excel-type-tag${typeCls}">${escapeHtml(row.type)}</span></td>
            <td class="check-excel-name">${escapeHtml(row.name)}</td>
            ${renderCheckExcelRowCells(row, showConv, showMatrix, showBoss)}
          </tr>`;
        })
        .join('')
    : `<tr><td colspan="${15 + Number(showConv) + Number(showMatrix) + Number(showBoss)}" class="check-excel-empty">编辑轴为空；请先在「编轴」添加技能后再对照</td></tr>`;

  const sum = rows.reduce((s, r) => s + (Number(r.bd?.total) || 0), 0);
  const critSum = rows.reduce(
    (s, r) => s + (Number(r.bd?.critTotal ?? r.bd?.total) || 0),
    0
  );
  const cycleOn = !!member?.cycleConfig?.enabled;
  const roundIndex = cycleOn
    ? typeof getActiveCycleRoundIndex === 'function'
      ? getActiveCycleRoundIndex(member)
      : 0
    : 0;
  const roundHint = cycleOn ? ` · 第${roundIndex + 1}轮` : '';

  const formulaFull =
    '倍率%；加深/攻击/增伤/暴击/暴伤/暴击期望/抗性/防御/易伤/集谐/额外易伤为乘算因子（减伤减免区×集谐·最终伤害区×矩阵第6类易伤区×Boss第8类易伤区×额外易伤区；区内加算、区间乘算，集谐/额外易伤列仅在生效时显示）。最终期望非暴与暴击各自 Floor 后按暴击率加权；暴击情况=全暴击各段 Floor 合计。特殊技能基数（处决 10027 / 效应 3674）已内置不展示；加深分效应加深，攻击为空；增伤分处决为谐幅、效应为加深。';

  return `
    <div class="check-excel-panel">
      <div class="check-excel-head">
        <h3>乘区对照表<span class="check-excel-sub">（按编轴左→右 · 可与 Excel 模板逐行核对${escapeHtml(roundHint)}）</span></h3>
        <div class="check-excel-totals">
          <div class="check-excel-total-item">
            <span class="check-excel-total-label">合计期望</span>
            <span class="check-excel-total-value">${fmt(Math.round(sum))}</span>
          </div>
          <div class="check-excel-total-item">
            <span class="check-excel-total-label">合计暴击</span>
            <span class="check-excel-total-value">${fmt(Math.round(critSum))}</span>
          </div>
        </div>
        <div class="check-excel-actions">
          <button type="button" class="btn sm" data-check-excel-export-copy title="把表格内容复制为制表符分隔文本，可直接粘贴到 Excel/WPS">复制表格</button>
          <button type="button" class="btn sm" data-check-excel-export-png title="把当前乘区对照表导出为图片">导出图片</button>
        </div>
      </div>
      <div class="check-formula-panel" data-formula-hint role="button" tabindex="0" aria-expanded="false" title="点击展开完整说明">
        <div class="check-formula-head">
          <span class="check-formula-title">计算说明</span>
          <span class="check-formula-chevron" aria-hidden="true">▾</span>
        </div>
        <div class="check-formula-body">${escapeHtml(formulaFull)}</div>
      </div>
      <div class="check-excel-top-scroll" data-check-excel-top-scroll aria-hidden="true">
        <div class="check-excel-top-inner"></div>
      </div>
      <div class="check-excel-scroll">
        <table class="check-excel-table">
          <colgroup>
            <col class="col-type" />
            <col class="col-name" />
            <col class="col-mult" />
            <col class="col-deep" />
            <col class="col-atk" />
            <col class="col-bonus" />
            <col class="col-crit" />
            <col class="col-cdmg" />
            <col class="col-cexpect" />
            <col class="col-res" />
            <col class="col-def" />
            <col class="col-total" />
            <col class="col-critcase" />
            <col class="col-vuln" />
            ${showConv ? '<col class="col-vuln-conv" />' : ''}
            ${showMatrix ? '<col class="col-vuln-matrix" />' : ''}
            ${showBoss ? '<col class="col-vuln-matrix" />' : ''}
            <col class="col-evuln" />
          </colgroup>
          <thead>
            <tr>
              <th class="check-excel-type">类型</th>
              <th class="check-excel-name">技能名</th>
              <th class="th-zone th-mult">倍率</th>
              <th class="th-zone th-deep">加深</th>
              <th class="th-zone th-atk">攻击</th>
              <th class="th-zone th-bonus">增伤</th>
              <th class="th-zone th-crit">暴击</th>
              <th class="th-zone th-cdmg">暴伤</th>
              <th class="th-zone th-cexpect">暴击期望</th>
              <th class="th-zone th-res">抗性</th>
              <th class="th-zone th-def">防御</th>
              <th class="check-excel-th-result check-excel-th-total">最终期望</th>
              <th class="check-excel-th-result check-excel-th-crit">暴击情况</th>
              <th class="th-zone th-vuln">易伤</th>
              ${showConv ? '<th class="th-zone th-vuln-conv">集谐</th>' : ''}
              ${showMatrix ? '<th class="th-zone">矩阵·第6类</th>' : ''}
              ${showBoss ? '<th class="th-zone">Boss·第8类</th>' : ''}
              <th class="th-zone th-evuln">额外易伤</th>
            </tr>
          </thead>
          <tbody>${body}</tbody>
        </table>
      </div>
    </div>`;
}

/** 乘区对照表 → 制表符分隔文本（可直接粘贴 Excel/WPS） */
function buildCheckExcelCopyText() {
  const table = document.querySelector('.check-excel-table');
  if (!table) return '';
  const rows = [...table.querySelectorAll('tr')].map((tr) =>
    [...tr.querySelectorAll('th,td')].map((c) => String(c.textContent || '').trim()).join('\t')
  );
  return rows.filter(Boolean).join('\n');
}

async function copyCheckExcelAsTable() {
  const text = buildCheckExcelCopyText();
  if (!text) return false;
  try {
    if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(text);
    else {
      const ta = document.createElement('textarea');
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      ta.remove();
    }
    return true;
  } catch (_) {
    return false;
  }
}

/** 乘区对照表 → PNG（克隆到离屏容器避免横向裁剪） */
async function exportCheckExcelPng() {
  try {
    const source = document.querySelector('.check-excel-panel');
    if (!source) return { ok: false, reason: '未找到乘区对照表' };
    const table = source.querySelector('.check-excel-table');
    if (!table) return { ok: false, reason: '未找到表格数据' };
    const rows = [...table.querySelectorAll('tr')].filter((tr) => tr.cells.length > 0);
    if (!rows.length) return { ok: false, reason: '表格为空' };
    const headerCells = rows[0].cells;
    const colCount = headerCells.length;
    const cellWidths = [];
    for (let c = 0; c < colCount; c += 1) {
      const w = Math.ceil(Number(headerCells[c].getBoundingClientRect().width) || 64);
      cellWidths.push(Math.max(40, w));
    }
    const rowHeight = 48;
    const scale = 2;
    const canvas = document.createElement('canvas');
    canvas.width = cellWidths.reduce((s, w) => s + w, 0) * scale;
    canvas.height = rows.length * rowHeight * scale;
    const ctx = canvas.getContext('2d');
    ctx.scale(scale, scale);
    const bodyBg = getComputedStyle(document.body).backgroundColor || '';
    const bg =
      bodyBg && bodyBg !== 'rgba(0, 0, 0, 0)' && bodyBg !== 'transparent'
        ? bodyBg
        : '#12151c';
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, canvas.width / scale, canvas.height / scale);
    const hasAlpha = (c) => {
      const m = String(c || '').match(/[\d.]+/g);
      if (!m) return false;
      if (c.indexOf('rgba') >= 0 || c.indexOf('hsla') >= 0) return Number(m[m.length - 1]) > 0.001;
      return true;
    };
    const roundRect = (x, y, w, h, r) => {
      const rr = Math.max(0, Math.min(r, h / 2, w / 2));
      if (typeof ctx.roundRect === 'function') ctx.roundRect(x, y, w, h, rr);
      else ctx.rect(x, y, w, h);
    };
    let y = 0;
    rows.forEach((tr, ri) => {
      const isHead = ri === 0;
      let x = 0;
      const rowBg = getComputedStyle(tr).backgroundColor || '';
      for (let c = 0; c < tr.cells.length && c < colCount; c += 1) {
        const cell = tr.cells[c];
        const w = cellWidths[c];
        const cs = getComputedStyle(cell);
        let cellBg = cs.backgroundColor || '';
        if (!hasAlpha(cellBg)) cellBg = hasAlpha(rowBg) ? rowBg : bg;
        const fg = cs.color || (isHead ? '#151210' : '#aab4c2');
        ctx.fillStyle = cellBg;
        ctx.fillRect(x, y, w, rowHeight);
        ctx.fillStyle = fg;
        ctx.font = `${cs.fontWeight || (isHead ? '700' : '400')} ${cs.fontSize || '13px'} ${cs.fontFamily || 'sans-serif'}`;
        const tag = cell.querySelector('.check-excel-type-tag');
        if (tag) {
          const tcs = getComputedStyle(tag);
          const text = String(tag.textContent || '').trim();
          const tagBg = tcs.backgroundColor || 'rgba(0,0,0,0)';
          const tagFg = tcs.color || fg;
          const padX = isNaN(parseFloat(tcs.paddingLeft)) ? 8 : parseFloat(tcs.paddingLeft);
          const radius = isNaN(parseFloat(tcs.borderRadius)) ? 10 : parseFloat(tcs.borderRadius);
          ctx.save();
          ctx.font = `${tcs.fontWeight || '600'} ${tcs.fontSize || '12px'} ${tcs.fontFamily || 'sans-serif'}`;
          ctx.fillStyle = tagBg;
          const tw = text ? ctx.measureText(text).width : 0;
          const tx0 = Math.max(x + 3, x + (w - tw - padX * 2 - 6) / 2);
          const fh = isNaN(parseFloat(tcs.fontSize)) ? 12 : parseFloat(tcs.fontSize);
          const tagH = Math.max(16, Math.min(rowHeight - 6, Math.round(fh + 8)));
          const tagY = y + (rowHeight - tagH) / 2;
          roundRect(tx0, tagY, Math.min(w - 6, tw + padX * 2 + 6), tagH, Math.min(radius, tagH / 2));
          ctx.fill();
          ctx.fillStyle = tagFg;
          ctx.textAlign = 'left';
          ctx.textBaseline = 'middle';
          ctx.fillText(text, tx0 + padX, tagY + tagH / 2);
          ctx.restore();
        } else {
          const text = String(cell.textContent || '').trim();
          if (text) {
            ctx.textAlign = cs.textAlign === 'right' ? 'right' : cs.textAlign === 'left' ? 'left' : 'center';
            ctx.textBaseline = 'middle';
            const pad = isNaN(parseFloat(cs.paddingLeft)) ? 8 : parseFloat(cs.paddingLeft);
            const px = ctx.textAlign === 'right' ? x + w - pad : ctx.textAlign === 'left' ? x + pad : x + w / 2;
            ctx.fillText(text, px, y + rowHeight / 2, w - pad * 2);
          }
        }
        ctx.strokeStyle = 'rgba(128,128,128,0.22)';
        ctx.lineWidth = 1;
        ctx.strokeRect(x + 0.5, y + 0.5, w - 1, rowHeight - 1);
        x += w;
      }
      y += rowHeight;
    });
    const url = canvas.toDataURL('image/png');
    const a = document.createElement('a');
    const name = String(getActiveMember()?.name || '角色').replace(/[\\/:*?"<>|]/g, '_');
    a.href = url;
    a.download = `${name}-乘区对照表.png`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    return { ok: true };
  } catch (e) {
    return { ok: false, reason: '导出图片失败：' + String((e && e.message) || e) };
  }
}

/** 矩阵行：某 Buff 在当前乘区下提供的数值文本（展示用，不改计算） */
function getBuffZoneValueText(buff, zone, member) {
  if (!buff || !zone) return '';
  const catSet = new Set(zone.cats || []);
  const stacks = member?.globalBuffStacks || {};
  const opts = member ? { member } : undefined;
  const fmtV = (v) => {
    const n = Number(v) || 0;
    return `${n > 0 ? '+' : ''}${formatBuffPct(n)}`;
  };
  if (typeof isCompositeBuff === 'function' && isCompositeBuff(buff)) {
    const parts = [];
    (buff.effects || []).forEach((fx) => {
      const zid = String(fx?.zone || '');
      if (!catSet.has(zid)) return;
      const resolved =
        typeof resolveCompositeEffectRuntime === 'function'
          ? resolveCompositeEffectRuntime(buff, fx)
          : fx;
      const v = Number(resolved?.value) || 0;
      if (!(v > 0)) return;
      const label = String(buff.name || '').trim();
      const scopeNote = String(resolved?.skillScope || '') === 'names' ? '（指定技能）' : '';
      parts.push(`${label}${scopeNote} ${fmtV(v)}`);
    });
    return parts.length ? parts.join('；') : '';
  }
  if (!catSet.has(buff.category)) return '';
  const v = getBuffEffectiveValue(buff, stacks, opts);
  if (!(Number(v) > 0)) return '';
  if (typeof isStackBuff === 'function' && isStackBuff(buff)) {
    const cur = window.__WC.normalizeStackInput(stacks?.[buff.id] ?? 0, buff);
    return `每层${fmtV(buff.perStack)} × ${cur}层`;
  }
  return fmtV(v);
}

/** 乘区构成：面板来源逐行（展示用，不改计算） */
function collectZonePanelSources(zoneId, char, member, damageElement, damageType, scaleStat) {
  const rows = [];
  const push = (statKey, tag) => {
    const key = typeof charStatSourcesKey === 'function' ? charStatSourcesKey(statKey) : statKey + 'Sources';
    (char?.[key] || []).forEach((s) => {
      const v = Number(s?.value) || 0;
      if (!(v > 0)) return;
      if (zoneId === 'bonus' && damageElement) {
        // 属性增伤面板来源须与技能实际元素匹配（声骸/套装/手填按元素过滤）
        let srcEl = '';
        if (typeof parseAttrSourceElement === 'function') srcEl = parseAttrSourceElement(s);
        if (!srcEl) {
          const charEl = member ? getMemberElementLabel(member) : '';
          srcEl = charEl;
        }
        if (srcEl && srcEl !== damageElement) return;
      }
      rows.push({
        kind: 'panel',
        name: String(s?.name || tag || statKey).trim(),
        valuePct: v,
        tag: tag || '面板',
      });
    });
  };
  if (zoneId === 'atk' && (scaleStat === 'hp' || scaleStat === 'def')) {
    if (scaleStat === 'hp') {
      push('hpPercent', '生命%');
      push('flatHp', '固定生命');
    } else {
      push('defPercent', '防御%');
      push('flatDef', '固定防御');
    }
  } else if (zoneId === 'atk') {
    push('atkPercent', '攻击%');
    push('flatAtk', '固定攻击');
  } else if (zoneId === 'bonus') {
    push('attrBonus', '增伤');
    // 修复：类型增伤（副词条/武器/声骸）面板来源——按技能实际伤害类型过滤（重击/普攻/共鸣技能等）
    const typeKey = typeof charStatSourcesKey === 'function' ? charStatSourcesKey('typeDmgBonus') : 'typeDmgBonusSources';
    (char?.[typeKey] || []).forEach((s) => {
      const v = Number(s?.value) || 0;
      if (!(v > 0)) return;
      // 面板来源可能缺 damageType 字段（套装/主位 typeDmgBonus 只写 id/name/value）：
      // 用 parseTypeSourceDamageType 从 id/名称解析（echo_set_panel_*_type_普攻 → 普攻），
      // 与结算端 getManualTypeDmgBonusForType 同口径过滤。
      const st = String(
        s?.damageType ||
          (typeof parseTypeSourceDamageType === 'function' ? parseTypeSourceDamageType(s) : '') ||
          ''
      ).trim();
      if (st && st !== damageType) return;
      rows.push({
        kind: 'panel',
        name: String(s?.name || '类型增伤').trim(),
        valuePct: v,
        tag: '面板',
      });
    });
  } else if (zoneId === 'critRate') {
    push('critRate', '暴击');
  } else if (zoneId === 'critDmg') {
    push('critDmg', '暴伤');
  }
  return rows;
}

/** 乘区构成：Buff 逐条（与结算同口径过滤，展示用） */
function collectZoneBuffEntries(zoneCats, ctx, opts) {
  const { unit, parentSkill, member, active, stacks } = opts;
  const damageType = ctx.damageType;
  const damageElement = ctx.damageElement;
  const damageEffectType = ctx.damageEffectType;
  const buffs = member.buffs || [];
  const entries = [];
  const exclusiveEntries = new Map();
  const catSet = new Set(zoneCats || []);
  const pushEntry = (buff, label, value, note) => {
    const v = Number(value) || 0;
    if (!(v > 0) && !(buff?.category === 'matrixFinal' && v < 0)) return;
    const entry = {
      kind: 'buff',
      name: label || String(buff?.name || '').trim() || 'Buff',
      valuePct: v,
      tag: buff?.teamSourceId ? '团队' : '个人',
      stackInfo:
        typeof isStackBuff === 'function' && isStackBuff(buff)
          ? {
              cur: window.__WC.normalizeStackInput(stacks?.[buff.id] ?? 0, buff),
              max: buff.maxStacks,
            }
          : undefined,
      note: note || '',
    };
    const group = buff?.category === 'matrixFinal' ? buff.matrixSource?.exclusiveGroup : '';
    if (group) {
      const index = exclusiveEntries.get(group);
      if (index !== undefined) {
        if (v > entries[index].valuePct) entries[index] = entry;
        return;
      }
      exclusiveEntries.set(group, entries.length);
    }
    entries.push(entry);
  };
  buffs.forEach((buff) => {
    if (!active?.[buff.id]) return;
    if (typeof buffMatchesResolvedCombatMode === 'function' && !buffMatchesResolvedCombatMode(buff, { member })) {
      return;
    }
    if (typeof isCompositeBuff === 'function' && isCompositeBuff(buff)) {
      (buff.effects || []).forEach((fx) => {
        const zid = String(fx?.zone || '');
        if (!catSet.has(zid)) return;
        const resolved =
          typeof resolveCompositeEffectRuntime === 'function'
            ? resolveCompositeEffectRuntime(buff, fx)
            : fx;
        if (
          typeof compositeEffectMatchesFilters === 'function' &&
          !compositeEffectMatchesFilters(resolved, zid, damageType, {
            ...opts,
            damageElement,
            effectType: damageEffectType,
          })
        ) {
          return;
        }
        if (
          typeof compositeEffectAppliesToUnit === 'function' &&
          !compositeEffectAppliesToUnit(resolved, unit, parentSkill, member)
        ) {
          return;
        }
        if (
          typeof compositeEffectMeetsMinResonance === 'function' &&
          !compositeEffectMeetsMinResonance(resolved, member, buff)
        ) {
          return;
        }
        if (
          typeof compositeEffectMeetsTargetFilters === 'function' &&
          !compositeEffectMeetsTargetFilters(resolved, member)
        ) {
          return;
        }
        const effStacks = getCompositeBuffEffectiveStacks(buff, stacks, member);
        const effValue =
          typeof getCompositeEffectValue === 'function'
            ? getCompositeEffectValue(resolved, effStacks)
            : Number(resolved?.value) || 0;
        const label =
          String(buff?.name || '').trim() +
          (String(resolved?.skillScope || '') === 'names' ? '（指定技能）' : '');
        pushEntry(buff, label, effValue);
      });
      return;
    }
    if (buff.category === 'matrixFinal') {
      if ((buff.matrixSource?.zoneClass ?? 6) !== (opts.environmentZoneClass ?? 6)) return;
      if (!catSet.has('matrixFinal') || !window.__WC.matchesMatrixFinalBuff(buff, damageType, {...opts, damageElement, effectType:damageEffectType})) return;
    } else if (!catSet.has(buff.category)) return;
    if (typeof ELEMENT_TYPED_BUFF_CATS !== 'undefined' && ELEMENT_TYPED_BUFF_CATS?.has?.(buff.category)) {
      if (!damageElement) return;
      const el = String(buff.element || '');
      if (el && el !== BUFF_ELEMENT_GENERAL && el !== damageElement) return;
    } else if (typeof TYPED_BUFF_CATS !== 'undefined' && TYPED_BUFF_CATS?.has?.(buff.category)) {
      if (!typedBuffMatchesDamageContext(buff, damageType, damageEffectType, opts)) return;
    }
    const v = buff.category === 'matrixFinal'
      ? window.__WC.sumMatrixFinalPct({[buff.id]:true}, damageType, [buff], stacks, {...opts, damageElement, effectType:damageEffectType}, buff.matrixSource?.zoneClass ?? 6)
      : getBuffEffectiveValue(buff, stacks, { member });
    pushEntry(buff, String(buff?.name || '').trim(), v);
  });
  return entries;
}

/** 乘区构成收集器：返回来源清单 + 公式 + 自检（展示用，不改计算） */
function collectZoneComposition(zoneId, ctx) {
  const member = ctx?.member;
  const unit = ctx?.hitContext ? ctx.hitContext.hit : ctx?.unit;
  const parentSkill = ctx?.hitContext ? ctx?.unit : ctx?.parentSkill;
  const active = ctx?.hitContext ? ctx.hitContext.active : ctx?.active;
  const stacks = ctx?.hitContext ? ctx.hitContext.stacks : ctx?.stacks;
  const bd = ctx?.hitContext ? ctx.hitContext.breakdown : ctx?.breakdown;
  const autoSeg = !!ctx?.autoSegmented && !!ctx?.hitContext;
  const base = {
    unit,
    parentSkill,
    member,
    active,
    stacks,
    damageType: getUnitDamageType(unit, parentSkill),
    damageElement: getUnitDamageElement(unit, parentSkill, member),
    damageEffectType: getUnitEffectType(unit, parentSkill, member),
    alsoDamageTypes: getUnitAlsoDamageTypes(unit, parentSkill, member),
    scaleStat:
      typeof getUnitScaleStat === 'function' ? getUnitScaleStat(unit, parentSkill) : 'atk',
  };
  const opts = {
    unit,
    parentSkill,
    member,
    active,
    stacks,
    brantLifeMode: resolveBrantLifeMode(unit, parentSkill, member),
    combatMode: resolvePhoebeCombatMode(unit, parentSkill, member),
    environmentZoneClass: ({vuln:2,matrix:6,boss:8})[zoneId],
    alsoDamageTypes: base.alsoDamageTypes,
  };
  const fmt = (n, d = 2) => (Number.isFinite(Number(n)) ? Number(n).toFixed(d).replace(/\.?0+$/, '') : '—');
  const pct = (n) => `${Number(n) > 0 ? '+' : ''}${fmt(n)}%`;
  const defs = {
    mult: { label: '倍率', cats: ['multAdd', 'multBoost', 'multBoostExtra'], bdKey: 'skillMult' },
    deep: { label: '加深', cats: ['generalDeep', 'elementDeep', 'typeDeep'], bdKey: 'deepening' },
    atk: { label: '攻击', cats: ['generalAttack', 'typeAttack', 'flatAtk'], bdKey: 'attack' },
    bonus: { label: '增伤', cats: ['generalBonus', 'elementBonus', 'typeBonus'], bdKey: 'dmgBonus' },
    critRate: { label: '暴击', cats: ['generalCritRate', 'elementCritRate', 'typeCritRate', 'critRateSet'], bdKey: 'critRatePct' },
    critDmg: { label: '暴伤', cats: ['generalCritDmg', 'elementCritDmg', 'typeCritDmg'], bdKey: 'critDmgPct' },
    res: { label: '抗性', cats: ['generalResReduce', 'elementResReduce', 'typeResReduce'], bdKey: 'resistance' },
    def: { label: '防御', cats: ['generalDefense', 'elementDefense', 'typeDefense'], bdKey: 'defense' },
    vuln: { label: '易伤', cats: ['generalVulnerability', 'elementVulnerability', 'typeVulnerability', 'matrixFinal'], bdKey: 'vulnerability' },
    matrix: { label: '第6类易伤·矩阵', cats: ['matrixFinal'], bdKey: 'matrixFinal' },
    boss: { label: '第8类易伤·Boss', cats: ['matrixFinal'], bdKey: 'bossFinal' },
    conv: { label: '集谐·最终伤害', cats: ['convergence'], bdKey: 'convergenceVuln' },
    extraVuln: { label: '额外易伤', cats: ['extraVulnerability'], bdKey: 'extraVulnerability' },
    critExpect: { label: '暴击期望', cats: [], bdKey: 'critExpect' },
    total: { label: '最终期望', cats: [], bdKey: 'total' },
    critTotal: { label: '暴击情况', cats: [], bdKey: 'critTotal' },
  };
  const def = defs[zoneId] || defs.bonus;
  const sources = [];
  let formulaText = '';
  let formulaKind = 'add';
  let expected = Number(bd?.[def.bdKey]) || 0;
  const char = member?.char || {};
  const sumEntries = (arr) => arr.reduce((s, e) => s + (Number(e.valuePct) || 0), 0);

  if (zoneId === 'mult') {
    const baseRaw = Number(bd?.baseMultRaw) || 0;
    const addEntries = collectZoneBuffEntries(['multAdd'], base, opts);
    const boostEntries = collectZoneBuffEntries(['multBoost'], base, opts);
    const extraEntries = collectZoneBuffEntries(['multBoostExtra'], base, opts);
    const addSum = sumEntries(addEntries);
    const boostSum = sumEntries(boostEntries);
    const extraSum = sumEntries(extraEntries);
    // 拆分结算（真 split 或 autoSegmented）时，倍率增加按基础倍率占比分摊到本段
    // （与结算 resolveUnitMultAddPct 同口径）；整行聚合时 bd.multAddPct === addSum，ratio=1。
    let addRatio = 1;
    const bdAdd = Number(bd?.multAddPct);
    if (addSum > 0 && Number.isFinite(bdAdd) && Math.abs(bdAdd - addSum) > 1e-6) {
      addRatio = Math.max(0, bdAdd / addSum);
    }
    if (baseRaw > 0) sources.push({ kind: 'base', name: '基础倍率', valuePct: baseRaw, tag: '基础' });
    sources.push(
      ...addEntries.map((e) => ({
        ...e,
        name: `倍率增加 · ${e.name}`,
        valuePct: Number(e.valuePct) * addRatio,
        note: (e.note ? e.note + '；' : '') + (addRatio !== 1 ? '按基础占比分摊至本段' : ''),
      }))
    );
    sources.push(...boostEntries.map((e) => ({ ...e, name: `倍率提升 · ${e.name}` })));
    sources.push(...extraEntries.map((e) => ({ ...e, name: `额外倍率提升 · ${e.name}` })));
    formulaKind = 'custom';
    const addShown = addRatio !== 1 ? bdAdd : addSum;
    formulaText = `(${fmt(baseRaw)}% + ${fmt(addShown)}%) × (1+${fmt(boostSum)}%) × (1+${fmt(extraSum)}%)`;
    if (boostEntries.length > 1) {
      formulaText += `（倍率提升 ${boostEntries.length} 个来源区内加算，非各自乘算）`;
    }
    const displayCount = normalizeMultCount(bd?.multCount);
    if (displayCount !== 1) formulaText += ` × ${displayCount} 次`;
    expected = (baseRaw / 100 + addShown / 100) * (1 + boostSum / 100) * (1 + extraSum / 100) * displayCount;
  } else if (zoneId === 'deep' || zoneId === 'bonus' || zoneId === 'vuln') {
    const cats = def.cats;
    const entries = collectZoneBuffEntries(cats, base, opts);
    sources.push(...collectZonePanelSources(zoneId, char, member, base.damageElement, base.damageType));
    sources.push(...entries);
    const sum = sumEntries(sources);
    formulaKind = 'add';
    // 85% 本身即 85/100，再写 /100 会双重除（读作 1.0085）。正确写法 1 + 85% = 1.85。
    formulaText = `1 + ${fmt(sum)}%`;
    expected = 1 + sum / 100;
  } else if (zoneId === 'atk') {
    const statMode = base.scaleStat === 'hp' || base.scaleStat === 'def' ? base.scaleStat : 'atk';
    const statCats =
      statMode === 'hp'
        ? ['generalHpPct']
        : statMode === 'def'
          ? ['generalDefPct']
          : def.cats;
    const entries = collectZoneBuffEntries(statCats, base, opts);
    sources.push(...collectZonePanelSources('atk', char, member, undefined, undefined, statMode));
    sources.push(...entries);
    const statLabel = statMode === 'hp' ? '生命' : statMode === 'def' ? '防御' : '攻击';
    const pctSum = sumEntries(sources.filter((s) => !String(s.tag || '').startsWith('固定')));
    const flatSum = sumEntries(sources.filter((s) => String(s.tag || '').startsWith('固定')));
    formulaKind = 'custom';
    formulaText = `${statLabel}基础×(1+${fmt(pctSum)}%) + 固定${statLabel} ${fmt(flatSum)}`;
  } else if (zoneId === 'critRate' || zoneId === 'critDmg') {
    const entries = collectZoneBuffEntries(def.cats, base, opts);
    sources.push(...collectZonePanelSources(zoneId, char, member));
    sources.push(...entries);
    const sum = sumEntries(sources);
    formulaKind = 'add';
    formulaText = `面板Σ + BuffΣ = ${fmt(sum)}%`;
  } else if (zoneId === 'res') {
    const originalRes = Number(state?.team?.monsterRes) || 0;
    const monsterRes = window.__WC.getMatrixTargetResistancePct(originalRes, active, base.damageType, member?.buffs, stacks, {
      ...opts, damageElement: base.damageElement, effectType: base.damageEffectType,
    });
    const entries = collectZoneBuffEntries(def.cats, base, opts);
    const overridden = monsterRes !== originalRes;
    if (monsterRes > 0 || overridden) sources.push({ kind: 'base', name: overridden ? '基础抗性（Boss覆盖）' : '基础抗性（怪物）', valuePct: monsterRes, tag: overridden ? '覆盖' : '基础' });
    sources.push(...entries);
    const resReduce = sumEntries(entries);
    expected = calcResistanceMultiplier(monsterRes, resReduce);
    formulaKind = 'custom';
    formulaText = `1 − ${fmt(monsterRes)}% + ${fmt(resReduce)}% = ${fmt(expected, 4)}（超过 1 的部分减半）`;
  } else if (zoneId === 'def') {
    const level = Number(state?.team?.monsterLevel) || 0;
    const levelPart = 792 + level * 8;
    const entries = collectZoneBuffEntries(def.cats, base, opts);
    sources.push({ kind: 'base', name: `等级项（${level} 级）`, valuePct: levelPart, tag: '基础' });
    sources.push(...entries);
    formulaKind = 'custom';
    const attackerDefense = (window.__WC.characterLevels?.defenseConstant(member) ?? DEF_CONST);
    sources.unshift({ kind: 'base', name: `角色等级（${(window.__WC.characterLevels?.level(member) ?? member.characterLevel ?? 90)} 级）`, valuePct: attackerDefense, tag: '基础' });
    formulaText = `${attackerDefense} / (${levelPart} × (1−穿防) × (1−无视) + ${attackerDefense})`;
  } else if (zoneId === 'conv' ||
    zoneId === 'matrix' ||
    zoneId === 'boss' || zoneId === 'extraVuln') {
    const entries = collectZoneBuffEntries(def.cats, base, opts);
    sources.push(...entries);
    const sum = sumEntries(sources);
    formulaKind = 'add';
    formulaText = `1 + ${fmt(sum)}%`;
    expected = 1 + sum / 100;
  } else if (zoneId === 'critExpect') {
    formulaKind = 'custom';
    formulaText = `暴击率 ${fmt(Number(bd?.critRatePct) || 0)}% × 暴伤 ${fmt(Number(bd?.critDmgPct) || 0)}% + (1 − 暴击率)`;
    expected = Number(bd?.critExpect) || 0;
  } else {
    // total / critTotal：各乘区连乘链
    const chain = [
      ['倍率', bd?.skillMult],
      ['加深', bd?.deepening],
      ['攻击', bd?.attack],
      ['增伤', bd?.dmgBonus],
      ['暴击期望', bd?.critExpect],
      ['抗性', bd?.resistance],
      ['防御', bd?.defense],
      ['易伤', bd?.vulnerability],
      ['矩阵', bd?.matrixFinal],
      ['Boss第8类', bd?.bossFinal ?? 1],
      ['集谐', bd?.convergenceVuln],
      ['额外易伤', bd?.extraVulnerability],
    ].filter(([, v]) => Number.isFinite(Number(v)) && Number(v) > 0);
    chain.forEach(([name, v]) => {
      sources.push({ kind: 'chain', name, valuePct: Number(v), tag: '乘区因子' });
    });
    formulaKind = 'mult';
    formulaText = chain.map(([name, v]) => `${name} ${fmt(v, 4)}`).join(' × ');
    expected = Number(bd?.[def.bdKey]) || 0;
  }

  const attributedPct = zoneId === 'mult' ? expected : sumEntries(sources);
  let attributedFactor = attributedPct;
  if (
    zoneId === 'deep' ||
    zoneId === 'bonus' ||
    zoneId === 'vuln' ||
    zoneId === 'conv' ||
    zoneId === 'matrix' ||
    zoneId === 'boss' ||
    zoneId === 'extraVuln'
  ) {
    attributedFactor = 1 + attributedPct / 100;
  } else if (zoneId === 'mult') {
    attributedFactor = expected;
  }
  const factorVal = zoneId === 'mult' ? getDisplayedSkillMult(bd) : Number(bd?.[def.bdKey]) ?? expected;
  const mismatch =
    (zoneId === 'deep' ||
      zoneId === 'bonus' ||
      zoneId === 'vuln' ||
      zoneId === 'conv' ||
    zoneId === 'matrix' ||
    zoneId === 'boss' ||
      zoneId === 'extraVuln' ||
      zoneId === 'critRate' ||
      zoneId === 'critDmg') &&
    Number.isFinite(factorVal) &&
    factorVal > 0 &&
    Math.abs(attributedFactor - factorVal) > 1e-6 &&
    Math.abs((attributedFactor - factorVal) / factorVal) > 1e-4;

  return {
    zoneId,
    label: def.label,
    factor: factorVal,
    total: Number(bd?.total) || 0,
    formulaKind,
    formulaText,
    sources,
    attributed: attributedFactor,
    expected,
    mismatch,
    delta: mismatch ? attributedFactor - factorVal : 0,
  };
}

/** 乘区构成弹窗 */
function openZoneCompositionModal(rowKey, zoneId) {
  const member = getActiveMember();
  if (!member) return;
  const rawKey = String(rowKey || '');
  let compCtx = null;
  let skillNameRaw = '';
  let ownerMember = member;
  if (rawKey.startsWith('special:')) {
    // 特殊技能（处决/效应）：走特殊技能自己的结算上下文与 breakdown
    const specialId = rawKey.slice('special:'.length);
    const special =
      typeof findSpecialSkill === 'function' ? findSpecialSkill(specialId) : null;
    if (!special) return;
    const sctx = resolveSpecialSkillContext(special);
    if (!sctx.member) return;
    ownerMember = sctx.member;
    const bd =
      special._breakdown ||
      (special.kind === 'effect'
        ? calcEffectBreakdown(special)
        : calcExecutionBreakdown(special));
    const stub = {
      name: special.name || '特殊技能',
      damageType: special.kind === 'effect' ? '效应' : '处决',
      libraryKey: special.libraryKey || '',
      librarySkillName: special.name || '',
      libraryName: special.name || '',
      effectType: special.effectType || '',
    };
    compCtx = {
      unit: stub,
      parentSkill: stub,
      member: sctx.member,
      active: sctx.active,
      stacks: sctx.stacks,
      phaseActive: null,
      breakdown: bd,
    };
    skillNameRaw = special.name || '特殊技能';
  } else {
    const [catalogId, hiStr] = rawKey.split(':');
    const hitIndex = hiStr === '' || hiStr === undefined ? null : Number(hiStr);
    const match =
      typeof findTimelineSkillByCatalog === 'function'
        ? findTimelineSkillByCatalog(catalogId)
        : null;
    if (match && match.skill && match.phase) {
      const ctx = getCheckSkillBreakdownContext(match.phase, match.skill, member);
      compCtx = ctx;
      if (hitIndex != null && Array.isArray(ctx.hits) && ctx.hits[hitIndex]) {
        compCtx = { ...ctx, hitContext: ctx.hits[hitIndex] };
      }
      skillNameRaw = match.skill.name || '技能';
    } else {
      // 修复：catalog 条目存在但时间线未入轴/未链接时不再静默 return——
      // 用 catalog 定义兜底构建上下文（面板/Buff 来源清单仍完整，breakdown 缺失则期望值显示为 0）
      const catItem = (member.rotationCatalog || []).find((c) => String(c.id) === String(catalogId));
      if (!catItem) return;
      compCtx = {
        unit: catItem,
        parentSkill: catItem,
        member,
        active: {},
        stacks: {},
        phaseActive: null,
        breakdown: null,
      };
      skillNameRaw = catItem.name || '技能';
    }
  }
  const comp = collectZoneComposition(zoneId, compCtx);
  const skillName = escapeHtml(String(skillNameRaw));
  const roundHint = ownerMember.cycleConfig?.enabled
    ? ` · 第${(typeof getActiveCycleRoundIndex === 'function' ? getActiveCycleRoundIndex(ownerMember) : 0) + 1}轮`
    : '';
  const rowsHtml = comp.sources
    .map((s) => {
      const stackHtml = s.stackInfo ? `（${s.stackInfo.cur}/${s.stackInfo.max}层）` : '';
      const valueText =
        s.kind === 'chain'
          ? `× ${fmt2(s.valuePct)}`
          : `${Number(s.valuePct) > 0 ? '+' : ''}${fmt2(s.valuePct)}%`;
      return `<tr>
        <td class="zone-comp-name">${escapeHtml(s.name)}</td>
        <td class="zone-comp-tag">${escapeHtml(s.tag || '')}</td>
        <td class="zone-comp-value">${valueText}</td>
        <td class="zone-comp-note">${escapeHtml((s.note || '') + stackHtml)}</td>
      </tr>`;
    })
    .join('');
  const mismatchHtml = comp.mismatch
    ? `<div class="zone-comp-warn">构成合计 ${fmt2(comp.attributed)} vs 最终值 ${fmt2(comp.expected)}，差 ${fmt2(comp.delta)}（可能有未列出的来源）</div>`
    : '';
  const overlay = document.createElement('div');
  overlay.className = 'ecm-overlay zone-comp-overlay';
  overlay.innerHTML = `
    <div class="ecm-modal zone-comp-modal" role="dialog" aria-modal="true">
      <div class="ecm-modal-head">
        <strong>${skillName} · ${escapeHtml(comp.label)}${escapeHtml(roundHint)}</strong>
        <button type="button" class="btn sm" data-zone-comp-close aria-label="关闭">×</button>
      </div>
      <div class="ecm-modal-body">
        <div class="zone-comp-formula">${escapeHtml(comp.formulaText)}</div>
        <div class="zone-comp-table-wrap">
          <table class="zone-comp-table">
            <thead><tr><th>来源</th><th>类型</th><th>数值</th><th>备注</th></tr></thead>
            <tbody>${rowsHtml || '<tr><td colspan="4" class="zone-comp-empty">该乘区无独立来源（仅公式）</td></tr>'}</tbody>
          </table>
        </div>
        <div class="zone-comp-total">最终因子 <strong>${fmt2(comp.factor)}</strong>${Number.isFinite(comp.total) && comp.total > 0 ? ` · 期望伤害 ${Math.round(comp.total)}` : ''}</div>
        ${mismatchHtml}
      </div>
    </div>`;
  document.body.appendChild(overlay);
  const close = () => overlay.remove();
  overlay.addEventListener('click', (ev) => {
    if (ev.target.closest('[data-zone-comp-close]') || ev.target === overlay) close();
  });
  const onKey = (ev) => {
    if (ev.key === 'Escape') {
      close();
      document.removeEventListener('keydown', onKey);
    }
  };
  document.addEventListener('keydown', onKey);
}

function fmt2(n) {
  // 乘区构成表与真实乘区同口径：保留 4 位小数（去尾零），避免 3.788 显示成 3.79 的假差异
  return Number.isFinite(Number(n)) ? Number(n).toFixed(4).replace(/\.?0+$/, '') : '—';
}

function renderCheckBuffRows(buffs, columns, focusBuffId, startRow, member, zone, scope = 'personal') {
  const verified = ensureCheckBuffVerifiedMap(member);
  const skillColStart = 3;
  const scopeCls = scope === 'team' ? ' is-team' : ' is-personal';
  // 单次渲染内缓存：getCheckBuffCellState 为纯函数（不读时间/无副作用），
  // 同一次 renderCheckBuffRows 中 member 与 zone 恒定（闭包常量，从未重赋值），
  // 仅 (buff, col) 变化；以对象引用作 key 保证「相同输入→命中、不同输入→重算」，
  // 缓存随函数返回丢弃，不跨渲染保留（避免状态变化后的陈旧命中）。
  const cellStateCache = new Map(); // buff -> Map(col -> state)
  const getCellState = (buff, col) => {
    let byCol = cellStateCache.get(buff);
    if (!byCol) {
      byCol = new Map();
      cellStateCache.set(buff, byCol);
    }
    const hit = byCol.get(col);
    if (hit !== undefined) return hit;
    const state = getCheckBuffCellState(buff, col, member, zone);
    byCol.set(col, state);
    return state;
  };
  return buffs
    .map((buff, bi) => {
      const row = startRow + bi;
      const focused = focusBuffId && String(focusBuffId) === String(buff.id);
      const tip = escapeHtml(formatCheckBuffTooltip(buff, member)).replace(/\n/g, '&#10;');
      const isProtected =
        typeof isForcedActiveSystemBuff === 'function' && isForcedActiveSystemBuff(buff);
      const buffOn = isProtected ? true : member?.globalBuffActive?.[buff.id] !== false;
      const toggleTitle = isProtected
        ? '系统 Buff：结算强制生效，不可关闭'
        : '全局开关：关闭后默认全部技能不吃此 Buff（单技能仍可点格子单独打开）';
      const linkedCols = (columns || []).filter((c) => c?.linked);
      const coveredCount = linkedCols.filter((col) =>
        isCheckBuffCoveringColumn(buff, col, member, zone)
      ).length;
      const totalCount = linkedCols.length;
      const covPct = totalCount > 0 ? (coveredCount / totalCount) * 100 : 0;
      const covShort =
        totalCount <= 0 ? '—' : covPct >= 99.995 ? '100%' : `${covPct.toFixed(1)}%`;
      const covTitle =
        totalCount > 0
          ? `覆盖率 ${coveredCount}/${totalCount}（${covShort}）· 按住 V 点击可标记；右键也可`
          : '当前无可统计技能列 · 按住 V 点击可标记；右键也可';
      const isVerified = !!verified[String(buff.id)];
      const verifiedCls = isVerified ? ' is-verified' : '';
      const rowFocus = focused ? ' is-row-focus active' : '';
      const shortName =
        shortBuffName(stripManagedBuffSourcePrefixes(buff.name) || buff.name) ||
        formatBuffDisplayName(buff) ||
        'Buff';
      const gameTextHit =
        typeof renderBuffGameTextHitAttrs === 'function' ? renderBuffGameTextHitAttrs(buff) : '';
      const gameTextInfo =
        typeof getBuffGameTextInfo === 'function' ? getBuffGameTextInfo(buff) : null;
      // 有游戏原文案时只走 WcTooltip，去掉原生 title，避免白色系统提示叠层
      const nameTitleAttr = gameTextInfo?.hasText
        ? ''
        : ` title="${tip}&#10;${escapeHtml(covTitle)}"`;
      const covTitleAttr = gameTextInfo?.hasText
        ? ''
        : ` title="${escapeHtml(covTitle)}"`;
      const nameInner = gameTextHit
        ? `<span class="buff-game-text-hit"${gameTextHit}>${escapeHtml(shortName)}</span>`
        : escapeHtml(shortName);
      const zoneValueText = getBuffZoneValueText(buff, zone, member);
      const zoneValueBadge = zoneValueText
        ? `<span class="check-buff-value-badge" title="该 Buff 在当前乘区提供的数值（展示用）">${escapeHtml(zoneValueText)}</span>`
        : '';
      const toggleCell = `<div class="check-buff-toggle-cell${scopeCls}${rowFocus}${verifiedCls}" style="grid-row:${row};grid-column:1" data-check-buff-row="${escapeHtml(String(buff.id))}">
        <input type="checkbox" data-check-buff-toggle="${escapeHtml(String(buff.id))}" ${buffOn ? 'checked' : ''} ${isProtected ? 'disabled' : ''} title="${toggleTitle}" />
      </div>`;
      const nameCell = `<div class="check-buff-name-cell${scopeCls}${rowFocus}${verifiedCls}" style="grid-row:${row};grid-column:2" data-check-buff-row="${escapeHtml(String(buff.id))}">
        <button type="button" class="check-buff-name-btn" data-check-focus-buff="${escapeHtml(String(buff.id))}"${nameTitleAttr}><span class="check-buff-name-text">${nameInner}</span>${zoneValueBadge}<span class="check-buff-cov-inline"${covTitleAttr}> · ${escapeHtml(covShort)}</span></button>
      </div>`;
      const cells = columns
        .map((col, ci) => {
          const state = getCellState(buff, col);
          const hl = focused && state.covered ? ' is-covered' : '';
          const colIdx = ci + skillColStart;
          if (state.kind === 'na') {
            return `<div class="check-cell na${rowFocus}${hl}${verifiedCls}" style="grid-row:${row};grid-column:${colIdx}"></div>`;
          }
          if (state.kind === 'mismatch') {
            return `<div class="check-cell no mismatch${rowFocus}${hl}${verifiedCls}" style="grid-row:${row};grid-column:${colIdx}" title="${escapeHtml(state.why || '不匹配')}"><span class="check-mark-box mismatch" aria-hidden="true">×</span></div>`;
          }
          const mark = state.covered
            ? '<span class="check-mark-box ok" aria-hidden="true">✓</span>'
            : '<span class="check-mark-box off" aria-hidden="true">—</span>';
          const cls = state.covered ? 'ok' : 'off';
          if (state.kind === 'locked' || isProtected) {
            const lockTip = isProtected ? '系统 Buff，结算强制生效' : '技能已锁定';
            return `<div class="check-cell ${cls}${rowFocus}${hl}${verifiedCls}" style="grid-row:${row};grid-column:${colIdx}" title="${lockTip}">${mark}</div>`;
          }
          return `<button type="button" class="check-cell ${cls}${rowFocus}${hl}${verifiedCls}" style="grid-row:${row};grid-column:${colIdx}" data-check-skill-buff="1" data-phase-id="${escapeHtml(String(state.phaseId))}" data-skill-id="${escapeHtml(String(state.skillId))}" data-buff-id="${escapeHtml(String(state.buffId))}" data-covered="${state.covered ? '1' : '0'}" title="${state.covered ? '点击：仅本技能关闭此 Buff' : '点击：仅本技能开启此 Buff'}">${mark}</button>`;
        })
        .join('');
      return toggleCell + nameCell + cells;
    })
    .join('');
}

function ensureCheckBuffVerifiedMap(member) {
  if (!member) return {};
  if (!member.checkBuffVerified || typeof member.checkBuffVerified !== 'object') {
    member.checkBuffVerified = {};
  }
  return member.checkBuffVerified;
}

function isCheckBuffVerified(member, buffId) {
  return !!ensureCheckBuffVerifiedMap(member)[String(buffId || '')];
}

function setCheckBuffVerified(member, buffId, verified) {
  if (!member || !buffId) return;
  const map = ensureCheckBuffVerifiedMap(member);
  const key = String(buffId);
  if (verified) map[key] = true;
  else delete map[key];
}

function closeCheckBuffCtxMenu() {
  const inspect = ensureCheckInspectState();
  if (inspect.ctxMenu) inspect.ctxMenu = null;
  // 右键菜单被移到 body 渲染（避开含 transform 的祖先导致 fixed 定位错位），关闭时同步摘除
  const el = document.querySelector('[data-check-buff-ctx]');
  if (el) el.remove();
}

function isCheckVerifyPaintHeld() {
  return !!ensureCheckInspectState().verifyPaintHeld;
}

function setCheckVerifyPaintHeld(held) {
  const inspect = ensureCheckInspectState();
  const next = !!held;
  if (!!inspect.verifyPaintHeld === next) return;
  inspect.verifyPaintHeld = next;
  document.body.classList.toggle('check-verify-paint', next);
  if (!next) return;
  setSaveStatus('按住 V · 点击 Buff 标记检查无误');
}

function applyCheckBuffVerifyPaint(member, buffId) {
  if (!member || !buffId) return false;
  setCheckBuffVerified(member, buffId, true);
  const inspect = ensureCheckInspectState();
  inspect.focusBuffId = String(buffId);
  closeCheckBuffCtxMenu();
  setSaveStatus('已标记检查无误');
  return true;
}

function renderCheckPanel(member) {
  computeMember(member);
  const inspect = ensureCheckInspectState();
  const columns = getCheckAxisColumns(member);
  const { zone, team, personal } = getCheckZoneBuffLists(member, inspect.zoneId);
  const charDef = member.characterId ? findCharSkillDef(member.characterId) : null;
  const colCount = Math.max(1, columns.length);

  const cycleOn = !!member.cycleConfig?.enabled;
  const roundIndex = cycleOn
    ? typeof getActiveCycleRoundIndex === 'function'
      ? getActiveCycleRoundIndex(member)
      : 0
    : 0;
  // 检查页约定：覆盖矩阵 / Excel / 页头总伤均对应当前编辑轮（非多轮合计）
  const checkRoundTotal = columns.reduce((s, c) => s + (Number(c.breakdown?.total) || 0), 0);
  const roundLabel = cycleOn ? `第${roundIndex + 1}轮` : '';
  const skillColStart = 3;

  const focusBuff = inspect.focusBuffId
    ? (member.buffs || []).find((b) => String(b.id) === String(inspect.focusBuffId))
    : null;
  const midLabel =
    zone.id === 'all' || zone.id === 'mult' ? '倍率' : String(zone.label || '倍率');
  const headCells = columns.length
    ? columns
        .map((col, ci) => {
          const covered =
            focusBuff && isCheckBuffCoveringColumn(focusBuff, col, member, zone);
          const missTag = col.linked
            ? ''
            : col.isSpecial
              ? '<span class="tag-miss">特殊技能</span>'
              : '<span class="tag-miss">未入轴</span>';
          // 仅首列保留行含义标签，其余列只显示数值，减少重复拥挤
          const showLabels = ci === 0;
          const skillVerified = !!(member.checkSkillVerified && member.checkSkillVerified[col.catalogId]);
          const labelExpect = showLabels
            ? '<span class="check-skill-metric-label">期望</span>'
            : '';
          const labelZone = showLabels
            ? `<span class="check-skill-metric-label">${escapeHtml(midLabel)}</span>`
            : '';
          const labelFinal = showLabels
            ? '<span class="check-skill-metric-label">最终</span>'
            : '';
          return `<div class="check-skill-head${showLabels ? ' has-metric-labels' : ''}${col.linked ? '' : ' not-linked'}${covered ? ' is-covered' : ''}${col.isSpecial ? ' is-special' : ''}${skillVerified ? ' is-skill-verified' : ''}" style="grid-row:1;grid-column:${ci + skillColStart}">
            <button type="button" class="check-skill-name${skillVerified ? ' is-verified' : ''}" data-check-skill-verify="${escapeHtml(String(col.catalogId))}" title="${escapeHtml(col.name)}${skillVerified ? '（已检查完毕，点击取消标记）' : '（点击标记该技能检查完毕）'}">${escapeHtml(col.name)}${skillVerified ? '<span class="check-skill-verified-badge" aria-label="已检查">✓</span>' : ''}</button>
            <div class="check-skill-metrics">
              <div class="check-skill-metric" title="该技能期望伤害">
                ${labelExpect}
                <span class="check-skill-metric-val is-expect">${formatCheckSkillDamage(col.breakdown)}</span>
              </div>
              <div class="check-skill-metric" title="当前乘区数值（${escapeHtml(midLabel)}）">
                ${labelZone}
                <span class="check-skill-metric-val is-zone">${formatCheckZoneValue(zone.id, col.breakdown)}</span>
              </div>
              <div class="check-skill-metric" title="最终倍率">
                ${labelFinal}
                <span class="check-skill-metric-val is-final">${formatCheckFinalMult(col.breakdown, col.catalogItem)}</span>
              </div>
            </div>
            ${missTag}
          </div>`;
        })
        .join('')
    : `<div class="check-empty" style="grid-row:1;grid-column:${skillColStart}">编辑轴为空，请先在「编轴」添加技能</div>`;

  let row = 2;
  let bodyHtml = '';
  // 全队
  bodyHtml += `<button type="button" class="check-section-toggle" style="grid-row:${row};grid-column:1" data-check-toggle-section="team" title="${inspect.teamCollapsed ? '展开' : '收起'}">${inspect.teamCollapsed ? '+' : '−'}</button>`;
  bodyHtml += `<div class="check-section-label" style="grid-row:${row};grid-column:2 / -1">
      <span class="sec-title">全队Buff</span>
      <span class="sec-count">该乘区下：${team.length}个</span>
    </div>`;
  row += 1;
  bodyHtml += `<div class="check-section-desc" style="grid-row:${row};grid-column:1 / -1">勾选为全局开关；格子√/×可点按单技能开关 · 点 Buff 名高亮覆盖列 · 按住 V 点击可标记检查无误</div>`;
  row += 1;
  if (!inspect.teamCollapsed) {
    if (!team.length) {
      bodyHtml += `<div class="check-buff-empty" style="grid-row:${row};grid-column:2">（无）</div>`;
      bodyHtml += `<div class="check-cell na" style="grid-row:${row};grid-column:${skillColStart} / span ${colCount}">${
        zone.id === 'all'
          ? '暂无全队 Buff'
          : `该乘区暂无全队Buff（复合Buff 会按效果出现在倍率/加深/增伤等对应乘区）`
      }</div>`;
      row += 1;
    } else {
      bodyHtml += renderCheckBuffRows(team, columns, inspect.focusBuffId, row, member, zone, 'team');
      row += team.length;
    }
  }
  // 个人
  bodyHtml += `<button type="button" class="check-section-toggle" style="grid-row:${row};grid-column:1" data-check-toggle-section="personal" title="${inspect.personalCollapsed ? '展开' : '收起'}">${inspect.personalCollapsed ? '+' : '−'}</button>`;
  bodyHtml += `<div class="check-section-label" style="grid-row:${row};grid-column:2 / -1">
      <span class="sec-title">个人Buff</span>
      <span class="sec-count">该乘区下：${personal.length}个</span>
    </div>`;
  row += 1;
  bodyHtml += `<div class="check-section-desc" style="grid-row:${row};grid-column:1 / -1">该乘区下个人 Buff · ${personal.length} 个</div>`;
  row += 1;
  if (!inspect.personalCollapsed) {
    if (!personal.length) {
      bodyHtml += `<div class="check-buff-empty" style="grid-row:${row};grid-column:2">（无）</div>`;
      bodyHtml += `<div class="check-cell na" style="grid-row:${row};grid-column:${skillColStart} / span ${colCount}">${
        zone.id === 'all'
          ? '暂无个人 Buff'
          : `该乘区暂无个人Buff（复合Buff 会按效果出现在倍率/加深/暴击/暴伤等对应乘区）`
      }</div>`;
    } else {
      bodyHtml += renderCheckBuffRows(personal, columns, inspect.focusBuffId, row, member, zone, 'personal');
    }
  }

  const gridCols =
    colCount > 0
      ? `44px 196px minmax(128px, 152px) repeat(${Math.max(0, colCount - 1)}, minmax(104px, 128px))`
      : `44px 196px`;
  const axisSeconds = cycleOn
    ? formatAxisDuration(getCycleTotalDuration(member))
    : formatAxisDuration(state.team.axisDuration);
  const summaryTotal = cycleOn
    ? Number(member.results?.cycleGrandTotal ?? member.results?.total) || 0
    : checkRoundTotal;
  const summaryDps = Number(member.results?.dps) || 0;
  const teamSummaryTotal = Number(state.teamResults?.total) || 0;
  const expectLabel = cycleOn ? `${roundLabel}合计期望` : '合计期望';
  const expectTotal = cycleOn
    ? Number(member.results?.cycles?.[roundIndex]?.total ?? checkRoundTotal) || 0
    : checkRoundTotal;

  const memberTabs = state.members
    .map((m, i) => {
      const active = !isSpecialView() && i === state.team.activeIndex ? ' is-active' : '';
      return `<button type="button" class="check-topbar-tab${active}" data-switch-member="${i}">${escapeHtml(m.name || `角色${i + 1}`)}</button>`;
    })
    .join('');
  const specialActive = isSpecialView() ? ' is-active' : '';
  const zoneChipDefs = (() => {
    const seenIds = new Set();
    const seenLabels = new Set();
    const list = [{ id: 'all', label: '全部' }];
    for (const z of BUFF_DAMAGE_ZONE_GROUPS || []) {
      const id = String(z?.id || '').trim();
      const label = String(z?.label || '').trim();
      if (!id || !label) continue;
      if (seenIds.has(id) || seenLabels.has(label)) continue;
      seenIds.add(id);
      seenLabels.add(label);
      list.push({ id, label });
    }
    return list;
  })();
  const zoneChips = zoneChipDefs
    .map(
      (z) =>
        `<button type="button" class="category-tab check-zone-chip${z.id === zone.id ? ' active' : ''}" data-check-zone="${escapeHtml(z.id)}" role="tab" aria-selected="${z.id === zone.id ? 'true' : 'false'}">${escapeHtml(z.label)}</button>`
    )
    .join('');

  const ctx = ensureCheckInspectState().ctxMenu;
  const ctxHtml =
    ctx && ctx.buffId
      ? `<div class="check-buff-ctx" style="left:${Number(ctx.x) || 0}px;top:${Number(ctx.y) || 0}px" data-check-buff-ctx>
          <button type="button" data-check-buff-verify="${escapeHtml(String(ctx.buffId))}" data-verify="${ctx.verified ? '0' : '1'}">${
            ctx.verified ? '取消标记' : '检查无误'
          }</button>
        </div>`
      : '';

  return `
    <div class="calc-check-page">
      <header class="check-topbar" aria-label="计算检查导航">
        <div class="check-topbar-left">
          <button type="button" class="check-topbar-link" data-workspace-phase="axis">← 编辑轴</button>
          <nav class="check-topbar-tabs" aria-label="角色切换">
            ${memberTabs}
            <button type="button" class="check-topbar-tab${specialActive}" data-switch-special>特殊技能</button>
          </nav>
        </div>
        <div class="check-topbar-center" aria-hidden="true"></div>
        <div class="check-topbar-right">
          <div class="check-topbar-stats" data-check-summary-bar>
            <div class="check-topbar-stat is-team-total">
              <span class="check-topbar-stat-label">全队总伤${cycleOn ? ' · 多轮' : ''}</span>
              <span class="check-topbar-stat-value">${fmt(teamSummaryTotal)}</span>
            </div>
            <div class="check-topbar-stat is-total">
              <span class="check-topbar-stat-label">总伤${cycleOn ? ' · 多轮' : ''}</span>
              <span class="check-topbar-stat-value">${fmt(summaryTotal)}</span>
            </div>
            <div class="check-topbar-stat">
              <span class="check-topbar-stat-label">轴长</span>
              <span class="check-topbar-stat-value">${axisSeconds}s</span>
            </div>
            <div class="check-topbar-stat">
              <span class="check-topbar-stat-label">DPS</span>
              <span class="check-topbar-stat-value">${fmt(summaryDps)}</span>
            </div>
            <div class="check-topbar-stat">
              <span class="check-topbar-stat-label">产能</span>
              <span class="check-topbar-stat-value" title="${escapeTooltip(formatAxisEnergyTitle(member.results))}">${formatAxisEnergyBaseValue(member.results)}</span>
            </div>
            <div class="check-topbar-stat">
              <span class="check-topbar-stat-label">回能</span>
              <span class="check-topbar-stat-value" title="${escapeTooltip(formatAxisEnergyTitle(member.results))}">${formatAxisEnergyValue(member.results)}</span>
            </div>
          </div>
          <button type="button" class="check-topbar-link check-topbar-link-end" data-workspace-phase="buff" title="Buff来源">
            <span class="check-topbar-link-full">Buff来源 →</span>
            <span class="check-topbar-link-icon" aria-hidden="true">→</span>
          </button>
        </div>
      </header>

      <section class="check-excel-section" aria-label="乘区对照表">
        ${renderCheckExcelTable(member)}
      </section>

      <section class="check-matrix-section" aria-label="核心Buff检查表">
        ${
          cycleOn
            ? `<div class="check-cycle-bar">
                <div class="cycle-round-tabs check-cycle-round-tabs">${renderCycleRoundTabs(member, { compact: true })}</div>
              </div>`
            : ''
        }
        <div class="check-matrix-title">
          <span class="check-char-name">${escapeHtml(charDef?.name || member.name || '未选角色')}</span>
          <span class="check-board-expect">${escapeHtml(expectLabel)}: <strong>${fmt(expectTotal)}</strong></span>
        </div>
        <div class="check-zone-section" aria-label="乘区选择">
          <div class="check-zone-bar">
            ${zoneChips}
          </div>
        </div>
        <div class="check-board">
          <div class="check-scroll">
            <div class="check-grid" style="grid-template-columns:${gridCols}">
              <div class="check-corner check-corner-toggle" style="grid-row:1;grid-column:1"></div>
              <div class="check-corner check-corner-name" style="grid-row:1;grid-column:2">Buff名称</div>
              ${headCells}
              ${bodyHtml}
            </div>
          </div>
        </div>
      </section>
      ${ctxHtml}
    </div>`;
}

function ensureExportCardDraft() {
  if (!state.exportCardDraft || typeof state.exportCardDraft !== 'object') {
    state.exportCardDraft = {
      axisName: state.schemeDraft?.name || '未命名轴',
      axisLength: Number(state.team?.axisDuration) || 20,
      difficulty: '',
      performance: '',
      axisKind: '',
      shareCode: '（网页上线后生成）',
    };
  } else {
    // 兼容旧字段 stability → performance
    if (
      state.exportCardDraft.performance == null &&
      state.exportCardDraft.stability != null
    ) {
      state.exportCardDraft.performance = String(state.exportCardDraft.stability || '');
    }
    if (!Number.isFinite(Number(state.exportCardDraft.axisLength))) {
      state.exportCardDraft.axisLength = Number(state.team?.axisDuration) || 20;
    }
    if (typeof normalizeAxisKind === 'function') {
      state.exportCardDraft.axisKind = normalizeAxisKind(state.exportCardDraft.axisKind);
    } else if (state.exportCardDraft.axisKind == null) {
      state.exportCardDraft.axisKind = '';
    }
  }
  return state.exportCardDraft;
}

/** 轻量刷新方案管理区展示（轴长 / 下拉占位态；卡面预览已改独立弹窗） */
function paintExportCardPreviewFromDraft() {
  ensureExportCardDraft();
  const card = state.exportCardDraft;
  const axisLen =
    Number(card.axisLength) > 0
      ? Number(card.axisLength)
      : Number(state.team?.axisDuration) || 20;
  const lenDisp = document.querySelector('[data-export-axis-len-display]');
  if (lenDisp) lenDisp.textContent = `${axisLen}s`;

  document.querySelectorAll('.esm-select[data-export-card-field]').forEach((el) => {
    el.classList.toggle('is-placeholder', !el.value);
  });
}

